//! Requests: the forms, saving, and deleting. Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.

use axum::http::StatusCode;
use board::models::request;
use board::routes::paths;

use super::submit;
use crate::factories;
use crate::support::TestApp;

#[tokio::test]
async fn new_renders_the_form() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    app.get(&paths::new_request())
        .await
        .assert_ok()
        .assert_contains(&format!("action=\"{}\"", paths::requests()));
}

#[tokio::test]
async fn create_saves_and_redirects_to_the_request() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let params = factories::request_params(app.db(), &me).await;
    let res = submit(&app, &paths::requests(), &params).await;
    let (rows, _) = request::all_for(app.db(), &me, board::models::Page::default())
        .await
        .unwrap();
    assert_eq!(rows.len(), 1, "one request saved");
    res.assert_redirect_to(&paths::request(rows[0].id));
    app.get(&paths::request(rows[0].id))
        .await
        .assert_ok()
        .assert_text("Request was successfully created.");
}

#[tokio::test]
async fn create_with_invalid_params_is_422_with_the_errors_and_the_input() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let mut params = factories::request_params(app.db(), &me).await;
    params.title = "".into();
    let res = submit(&app, &paths::requests(), &params).await;
    res.assert_status(StatusCode::UNPROCESSABLE_ENTITY)
        .assert_text("Title can't be blank");
    let (rows, _) = request::all_for(app.db(), &me, board::models::Page::default())
        .await
        .unwrap();
    assert!(rows.is_empty(), "nothing saved");
}

#[tokio::test]
async fn edit_shows_the_saved_values_and_update_saves_changes() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::request(app.db(), &me).await;
    app.get(&paths::edit_request(record.id))
        .await
        .assert_ok()
        .assert_contains(&format!("action=\"{}\"", paths::request(record.id)));
    let mut params = request::RequestParams::from(&record);
    params.title = "Changed by the test".into();
    submit(&app, &paths::request(record.id), &params)
        .await
        .assert_redirect_to(&paths::request(record.id));
    app.get(&paths::request(record.id))
        .await
        .assert_ok()
        .assert_text("Request was successfully updated.")
        .assert_text("Changed by the test");
}

#[tokio::test]
async fn update_with_invalid_params_is_422_and_changes_nothing() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::request(app.db(), &me).await;
    let mut params = request::RequestParams::from(&record);
    params.title = "".into();
    submit(&app, &paths::request(record.id), &params)
        .await
        .assert_status(StatusCode::UNPROCESSABLE_ENTITY)
        .assert_text("Title can't be blank");
    assert_eq!(
        factories::reload_request(app.db(), record.id).await,
        Some(record)
    );
}

#[tokio::test]
async fn destroy_cancels_and_redirects_to_the_list() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::request(app.db(), &me).await;
    app.post_form(&paths::delete_request(record.id), &[])
        .await
        .assert_redirect_to(&paths::requests());
    assert_eq!(
        factories::reload_request(app.db(), record.id)
            .await
            .unwrap()
            .status,
        request::RequestStatus::Cancelled
    );
    app.get(&paths::request(record.id)).await.assert_ok();
}

#[tokio::test]
async fn markup_in_a_request_is_shown_as_text() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let mut params = factories::request_params(app.db(), &me).await;
    params.title = "<script>alert(1)</script>".into();
    let record = factories::request_with(app.db(), &me, params).await;
    for path in [paths::requests(), paths::request(record.id)] {
        app.get(&path)
            .await
            .assert_ok()
            .assert_not_contains("<script>alert(1)")
            .assert_text("<script>alert(1)</script>");
    }
}
